  /** @LLM */ private static boolean isAtLeast24HoursBeforeDeparture(String bookingTime, String departureTime)
  {
    Date bookingDateTime = parseDateTime(bookingTime);
    Date departureDateTime = parseDateTime(departureTime);
    if (bookingDateTime == null || departureDateTime == null)
    {
      return false;
    }
    long diff = departureDateTime.getTime() - bookingDateTime.getTime();
    return diff >= 24L * 60L * 60L * 1000L;
  }

  /** @LLM */ private static Date parseDateTime(String value)
  {
    if (value == null)
    {
      return null;
    }
  
    String[] patterns = new String[]
    {
      "yyyy-MM-dd HH:mm:ss",
      "yyyy-MM-dd HH:mm",
      "yyyy/MM/dd HH:mm:ss",
      "yyyy/MM/dd HH:mm",
      "yyyy-MM-dd'T'HH:mm:ss",
      "yyyy-MM-dd'T'HH:mm"
    };
  
    for (String pattern : patterns)
    {
      try
      {
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat(pattern);
        sdf.setLenient(false);
        return sdf.parse(value);
      }
      catch (Exception e)
      {
        // try next pattern
      }
    }
    return null;
  }

  /** @LLM */ private static double roundToOneDecimal(double value)
  {
    return Math.round(value * 10.0d) / 10.0d;
  }

